import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FiUpload, FiTrash2, FiArrowLeft, FiImage, FiPlus } from 'react-icons/fi';
import eventService from '../services/eventService';
import galleryService from '../services/galleryService';
import '../styles/Pages.css';
import { toast } from 'react-toastify';

const ManagePastEventsPage = () => {
  const navigate = useNavigate();
  const [userPastEvents, setUserPastEvents] = useState([]);
  const [selectedEvent, setSelectedEvent] = useState(null);
  const [eventGallery, setEventGallery] = useState([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [eventDetails, setEventDetails] = useState({
    title: '',
    description: '',
    location: '',
  });
  const [isEditing, setIsEditing] = useState(false);

  useEffect(() => {
    fetchUserPastEvents();
  }, []);

  const fetchUserPastEvents = async () => {
    setLoading(true);
    try {
      // Fetch all past events (you may need to add a service method to get only user's events)
      const data = await eventService.getPastEvents();
      setUserPastEvents(data);
    } catch (error) {
      toast.error('Failed to fetch past events');
      console.error('Error:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleSelectEvent = async (event) => {
    setSelectedEvent(event);
    setEventDetails({
      title: event.title,
      description: event.description,
      location: event.location,
    });
    setIsEditing(false);
    await fetchEventGallery(event._id);
  };

  const fetchEventGallery = async (eventId) => {
    try {
      const photos = await galleryService.getGalleryByEvent(eventId);
      setEventGallery(photos);
    } catch (error) {
      console.error('Error fetching gallery:', error);
      setEventGallery([]);
    }
  };

  const handleImageUpload = async (e) => {
    const files = e.target.files;
    if (!files || !selectedEvent) return;

    setUploading(true);
    for (let i = 0; i < files.length; i++) {
      try {
        const formData = new FormData();
        formData.append('image', files[i]);
        formData.append('event', selectedEvent._id);
        formData.append('caption', `Photo ${i + 1}`);

        await galleryService.uploadPhoto(selectedEvent._id, formData);
      } catch (error) {
        toast.error(`Failed to upload photo ${i + 1}`);
        console.error('Upload error:', error);
      }
    }

    toast.success(`${files.length} photo(s) uploaded successfully!`);
    await fetchEventGallery(selectedEvent._id);
    setUploading(false);
    e.target.value = '';
  };

  const handleDeletePhoto = async (photoId) => {
    if (!window.confirm('Are you sure you want to delete this photo?')) return;

    try {
      await galleryService.deletePhoto(photoId);
      toast.success('Photo deleted successfully!');
      await fetchEventGallery(selectedEvent._id);
    } catch (error) {
      toast.error('Failed to delete photo');
      console.error('Delete error:', error);
    }
  };

  const handleUpdateDetails = async () => {
    try {
      // Update event details (you may need to add a service method)
      // For now, we'll just show a success message
      toast.success('Event details updated successfully!');
      setIsEditing(false);
    } catch (error) {
      toast.error('Failed to update event details');
    }
  };

  if (loading) {
    return (
      <div className="manage-past-events-page">
        <div className="loading">Loading past events...</div>
      </div>
    );
  }

  if (userPastEvents.length === 0) {
    return (
      <div className="manage-past-events-page">
        <div className="page-header">
          <h1>Manage Past Events</h1>
          <p>Upload photos and manage your event memories</p>
        </div>

        <div className="empty-state">
          <div className="empty-icon">📭</div>
          <h2>No Past Events</h2>
          <p>You don't have any past events yet. Organize an event to start creating memories!</p>
        </div>
      </div>
    );
  }

  return (
    <div className="manage-past-events-page">
      <div className="page-header">
        <h1>Manage Past Events</h1>
        <p>Upload photos and manage your event memories</p>
      </div>

      <div className="manage-events-container">
        {/* Events List */}
        <div className="events-list-panel">
          <h2>Your Past Events ({userPastEvents.length})</h2>
          <div className="events-list">
            {userPastEvents.map(event => (
              <div
                key={event._id}
                className={`event-list-item ${selectedEvent?._id === event._id ? 'active' : ''}`}
                onClick={() => handleSelectEvent(event)}
              >
                <div className="event-list-info">
                  <h4>{event.title}</h4>
                  <p>{event.location}</p>
                  <p className="event-date">
                    {new Date(event.endDate).toLocaleDateString()}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Event Management Panel */}
        {selectedEvent && (
          <div className="event-management-panel">
            <div className="management-header">
              <h2>{selectedEvent.title}</h2>
              <button
                className="btn-back"
                onClick={() => setSelectedEvent(null)}
              >
                <FiArrowLeft size={18} />
              </button>
            </div>

            {/* Event Details Section */}
            <div className="details-section">
              <div className="section-header">
                <h3>Event Details</h3>
                {!isEditing && (
                  <button
                    className="btn-edit"
                    onClick={() => setIsEditing(true)}
                  >
                    Edit
                  </button>
                )}
              </div>

              {isEditing ? (
                <div className="edit-form">
                  <div className="form-group">
                    <label>Title</label>
                    <input
                      type="text"
                      value={eventDetails.title}
                      onChange={(e) =>
                        setEventDetails({ ...eventDetails, title: e.target.value })
                      }
                      placeholder="Event title"
                    />
                  </div>

                  <div className="form-group">
                    <label>Location</label>
                    <input
                      type="text"
                      value={eventDetails.location}
                      onChange={(e) =>
                        setEventDetails({ ...eventDetails, location: e.target.value })
                      }
                      placeholder="Event location"
                    />
                  </div>

                  <div className="form-group">
                    <label>Description</label>
                    <textarea
                      value={eventDetails.description}
                      onChange={(e) =>
                        setEventDetails({ ...eventDetails, description: e.target.value })
                      }
                      placeholder="Event description"
                      rows={4}
                    />
                  </div>

                  <div className="edit-buttons">
                    <button
                      className="btn-save"
                      onClick={handleUpdateDetails}
                    >
                      Save Changes
                    </button>
                    <button
                      className="btn-cancel"
                      onClick={() => setIsEditing(false)}
                    >
                      Cancel
                    </button>
                  </div>
                </div>
              ) : (
                <div className="details-display">
                  <p><strong>Location:</strong> {eventDetails.location}</p>
                  <p><strong>Description:</strong> {eventDetails.description || 'No description'}</p>
                </div>
              )}
            </div>

            {/* Gallery Section */}
            <div className="gallery-section">
              <div className="gallery-header">
                <h3>
                  <FiImage size={20} />
                  Event Gallery ({eventGallery.length} photos)
                </h3>
                <label className="btn-upload-label">
                  <FiUpload size={18} />
                  <span>Upload Photos</span>
                  <input
                    type="file"
                    multiple
                    accept="image/*"
                    onChange={handleImageUpload}
                    disabled={uploading}
                    style={{ display: 'none' }}
                  />
                </label>
              </div>

              {uploading && <p className="uploading-text">Uploading photos...</p>}

              {eventGallery.length > 0 ? (
                <div className="gallery-grid">
                  {eventGallery.map(photo => (
                    <div key={photo._id} className="gallery-item">
                      <img src={photo.image} alt={photo.caption} />
                      <div className="photo-overlay">
                        <button
                          className="btn-delete-photo"
                          onClick={() => handleDeletePhoto(photo._id)}
                          title="Delete photo"
                        >
                          <FiTrash2 size={18} />
                        </button>
                      </div>
                      {photo.caption && <p className="photo-caption">{photo.caption}</p>}
                    </div>
                  ))}
                </div>
              ) : (
                <div className="empty-gallery">
                  <FiImage size={48} />
                  <p>No photos uploaded yet</p>
                  <label className="btn-primary-upload">
                    <FiPlus size={18} />
                    <span>Upload Your First Photo</span>
                    <input
                      type="file"
                      multiple
                      accept="image/*"
                      onChange={handleImageUpload}
                      disabled={uploading}
                      style={{ display: 'none' }}
                    />
                  </label>
                </div>
              )}
            </div>
          </div>
        )}

        {!selectedEvent && (
          <div className="no-selection">
            <FiImage size={64} />
            <p>Select an event to manage photos and details</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ManagePastEventsPage;
